// Central UI dictionary. Add a key here in both languages, then use t('key').
// Interpolation: use {name} in the string and pass t('key', { name: 'X' }).

export type Lang =
  | 'he' | 'en' | 'es' | 'fr' | 'de' | 'it' | 'pt' | 'ar' | 'zh' | 'ja' | 'ru' | 'hi'
  | 'ko' | 'tr' | 'pl' | 'nl' | 'id' | 'vi'
  | 'th' | 'el' | 'cs' | 'sv' | 'uk' | 'bn'

